import{_ as a,o as l,c as i,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Science Working Group 2021-09-22","description":"","frontmatter":{"title":"Ceph Science Working Group 2021-09-22","date":"2021-09-22T00:00:00.000Z","updated":"2021-10-07T00:00:00.000Z","tags":["Ceph","分布式存储","科学工作组","集群管理","硬件问题","软件升级"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Science_Working_Group_2021-09-22.md","filePath":"posts/2021/Ceph_Science_Working_Group_2021-09-22.md","lastUpdated":1780460162000}'),t={name:"posts/2021/Ceph_Science_Working_Group_2021-09-22.md"};function r(n,e,s,h,u,c){return l(),i("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议基本信息" tabindex="-1">会议基本信息 <a class="header-anchor" href="#会议基本信息" aria-label="Permalink to &quot;会议基本信息&quot;">​</a></h4><ul><li><strong>时间</strong>: 2021年9月22日</li><li><strong>主持人</strong>: 未提及</li><li><strong>参与者</strong>: 来自科学或研究计算环境中管理Ceph集群的人员</li></ul><h4 id="会议内容概述" tabindex="-1">会议内容概述 <a class="header-anchor" href="#会议内容概述" aria-label="Permalink to &quot;会议内容概述&quot;">​</a></h4><ul><li><strong>会议目的</strong>: 开放讨论，分享Ceph集群管理经验，讨论近期影响Ceph集群的问题和挑战。</li><li><strong>会议记录</strong>: 会议被录制并上传到YouTube频道。</li></ul><h4 id="主要讨论议题" tabindex="-1">主要讨论议题 <a class="header-anchor" href="#主要讨论议题" aria-label="Permalink to &quot;主要讨论议题&quot;">​</a></h4><ol><li><strong>新成员介绍</strong>: 新成员Joel介绍了自己的Ceph集群情况，该集群有6PB的存储，主要用于S3服务。</li><li><strong>Ceph集群配置和经验分享</strong>: 讨论了S3服务的性能优化，NVMe SSD的使用，以及网络故障后的集群恢复经验。</li><li><strong>Ceph版本升级和硬件问题</strong>: 讨论了从Nautilus到Octopus的升级经验，以及硬盘和NVMe的固件更新问题。</li><li><strong>Ceph集群的可用性和恢复</strong>: 分享了网络故障和电源故障后的集群恢复经验，强调了集群的自我恢复能力和数据完整性。</li><li><strong>Ceph的未来发展</strong>: 讨论了Ceph的容器化部署和Rocky Linux的使用。</li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续关注Ceph的最新版本和硬件更新。</li><li>计划进行Ceph版本的升级。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>定期举行会议，每两个月一次。</li><li>继续分享和讨论Ceph集群管理的经验和挑战。</li></ul><h4 id="其他备注" tabindex="-1">其他备注 <a class="header-anchor" href="#其他备注" aria-label="Permalink to &quot;其他备注&quot;">​</a></h4><ul><li>会议记录和讨论内容将被上传到YouTube频道供后续参考。</li><li>鼓励新成员加入并分享他们的经验，以促进知识共享和技术交流。</li></ul><h4 id="识别的错误、误解或遗漏的重要信息" tabindex="-1">识别的错误、误解或遗漏的重要信息 <a class="header-anchor" href="#识别的错误、误解或遗漏的重要信息" aria-label="Permalink to &quot;识别的错误、误解或遗漏的重要信息&quot;">​</a></h4><ul><li>原总结中未提及会议的录制和上传到YouTube频道的信息。</li><li>原总结中未提及对新成员Joel的集群配置细节的讨论。</li><li>原总结中未提及硬件问题，如NVMe SSD的问题。</li><li>原总结中未提及Ceph集群的可用性和恢复经验的详细讨论。</li></ul>',15)])])}const _=a(t,[["render",r]]);export{d as __pageData,_ as default};
